import {
  View,
  Text,
  ImageBackground,
  TouchableOpacity,
  FlatList,
} from 'react-native';
import React from 'react';
import styles from './styles';
import {useTranslation} from 'react-i18next';
import {useNavigation} from '@react-navigation/native';
import TextCM from '../../../../components/Text';
import {NavigationName, String} from '../../../../constants';
import {useAppSelector} from '../../../../hook/useRedux';
import {IconWhiteSetting, ImgHomeBanner} from '../../../../assets/images';

enum MenuType {
  Organization = 'Organization',
  DocumentType = 'DocumentType',
  Report = 'Report',
  Partner = 'Partner',
  History = 'History',
  User = 'User',
  Help = 'Help',
  Setting = 'Setting',
  CreateDocument = 'CreateDocument',
}

type MenuItem = {
  title: string;
  type: MenuType;
  icon: React.ReactNode;
};

const  Body = () => {
  const {t} = useTranslation();
  const navigation = useNavigation<any>();
  const user = useAppSelector(state => state.account.dataAccount);

  const LIST_MENU: MenuItem[] = [
    // {
    //   title: t('HM.TxtOrganization'),
    //   type: MenuType.Organization,
    //   icon: <IconWhiteOrganization width={(13)} height={(20)} />,
    // },
    // {
    //   title: t('HM.TxtDocumentType'),
    //   type: MenuType.DocumentType,
    //   icon: <IconWhiteDocument width={(10)} height={(20)} />,
    // },
    // {
    //   title: t('HM.TxtReport'),
    //   type: MenuType.Report,
    //   icon: <IconWhiteReport width={(10)} height={(20)} />,
    // },
    // {
    //   title: t('HM.TxtPartner'),
    //   type: MenuType.Partner,
    //   icon: <IconWhitePartner width={(17)} height={(20)} />,
    // },
    // {
    //   title: t('HM.TxtUser'),
    //   type: MenuType.User,
    //   icon: <IconWhiteUser width={(12)} height={(20)} />,
    // },
    // {
    //   title: t('HM.TxtHelp'),
    //   type: MenuType.Help,
    //   icon: <IconWhiteHelp width={(13)} height={(20)} />,
    // },
    // {
    //   title: t('HM.TxtCreateDocument'),
    //   type: MenuType.CreateDocument,
    //   icon: <IconWhiteRoundPlus width={(15)} height={(20)} />,
    // },
    {
      title: t('HM.TxtSetting'),
      type: MenuType.Setting,
      icon: <IconWhiteSetting width={13} height={20} />,
    },
    // {
    //   title: t('HM.TxtHistory'),
    //   type: MenuType.History,
    //   icon: <IconWhiteHistory width={(13)} height={(20)} />,
    // },
  ];

  const onPressItemMenu = (type: MenuType) => {
    switch (type) {
      case MenuType.Setting:
        navigation.navigate(NavigationName.GeneralSettingScreen as never);
        break;
      // case MenuType.CreateDocument:
      //   navigation.navigate(NavigationName.InfomationDocumentScreen as never);
      //   break;
      case MenuType.CreateDocument:
        navigation.navigate(NavigationName.InfomationDocumentScreen);
        break;
      case MenuType.History:
        navigation.navigate(NavigationName.ActivityHistoryScreen);
        break;
      default:
        break;
    }
  };

  const checkShowItem = (item: MenuItem) => {
    if (item.type === MenuType.User) {
      return user.authorities?.includes(String.ROLE.ROLE_ORG_ADMIN);
    }
    return true;
  };

  const renderItemMenu = ({item}: {item: MenuItem}) => {
    if (!checkShowItem(item)) {
      return null;
    }
    return (
      <TouchableOpacity
        style={styles.btnItem}
        onPress={() => {
          onPressItemMenu(item.type);
        }}>
        <View style={styles.viewIcon}>{item.icon}</View>
        <TextCM style={styles.txtItem}>{item.title}</TextCM>
      </TouchableOpacity>
    );
  };

  return (
    <View style={styles.container}>
      <ImageBackground source={ImgHomeBanner} style={styles.banner}>
        <TextCM style={styles.txtTitle}>{t('HM.TxtTitleBanner')}</TextCM>
        <TextCM style={styles.txtContent}>{t('HM.TxtContentBanner')}</TextCM>
      </ImageBackground>
      <View style={styles.body}>
        <FlatList
          data={LIST_MENU}
          numColumns={4}
          renderItem={renderItemMenu}
          scrollEnabled={false}
          contentContainerStyle={styles.contentBody}
        />
      </View>
    </View>
  );
};

export default Body;
