import {
  IParties,
  IRecipients,
} from '../../../model/interface/envelope.interface';
import {DocumentStatus, HistoryStatus} from '../helper';

export interface IExtendedRecipients extends IRecipients {
  partyName: string;
}

export const getListRecipient = (data: IParties[]) => {
  const listRecipient = data.map(item => {
    return item.recipients.map(recipient => {
      return {
        ...recipient,
        partyName: item.type === 'individual' ? '' : item.name,
      };
    });
  });

  return listRecipient.flat() as IExtendedRecipients[];
};

export const mappingShowHideAction = (
  documentStatus: string,
  historyStatus: string,
) => {
  if (documentStatus !== DocumentStatus.PROCESSING) {
    return {replace: false, notify: false};
  }
  switch (historyStatus) {
    case HistoryStatus.SIGNING:
    case HistoryStatus.STAMPING:
    case HistoryStatus.REVIEWING:
    case HistoryStatus.COORDINATING:
    case HistoryStatus.CCING:
      return {replace: true, notify: true};
    case HistoryStatus.WAIT_FOR_SIGNING:
    case HistoryStatus.WAIT_FOR_STAMPING:
    case HistoryStatus.WAIT_FOR_REVIEWING:
    case HistoryStatus.WAIT_FOR_COORDINATING:
    case HistoryStatus.WAIT_FOR_CC:
      return {replace: true, notify: false};
    default:
      return {replace: false, notify: false};
  }
};
