import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {Modal, ScrollView, TouchableOpacity, View} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import styles from './styles';

import {handleListHistoryRecipients, IServicesAvailability} from './helper';
import TextCM from '../../../../../components/Text';
import {DateUtils} from '../../../../../utils';
import {Font} from '../../../../../constants';
import {IcBlackLeftArrow} from '../../../../../assets/images';
import ButtonCM from '../../../../../components/Button';
import {useDocumentServices} from '../../../../../hook/apiHook/useApi';

type ModadlHistoryRecipientProp = {
  onClose: () => void;
  isVisible: boolean;
  documentId: string;
  recipientId: string;
  custId?: string;
};

const ModadlHistoryRecipient = ({
  onClose,
  isVisible,
  documentId,
  recipientId,
  custId,
}: ModadlHistoryRecipientProp) => {
  const {t} = useTranslation();
  const insets = useSafeAreaInsets();
  const [historyRecipients, setHistoryRecipients] = useState<any>([]);
  const [recipentHistory, setRecipentHistory] = useState<any>();
  const [serviceAvailable, setServiceAvailable] = useState<
    IServicesAvailability[]
  >([]);

  const DocumentServices = useDocumentServices();

  useEffect(() => {
    fetchRecipient();
    fetchServiceAvailable();
  }, []);

  const fetchRecipient = async () => {
    try {
      const res = await DocumentServices.getRecipentHistory(
        documentId,
        recipientId,
      );
      setRecipentHistory(res);
      setHistoryRecipients(handleListHistoryRecipients(res));
    } catch (error) {}
  };

  const fetchServiceAvailable = async () => {
    try {
      const res = await DocumentServices.getServiceAvailability(custId);
      setServiceAvailable(res);
    } catch (error) {}
  };

  const getValue = (dataTypes: string[], type: 'notify' | 'sign') => {
    if (!serviceAvailable) return '---';
    if (!dataTypes) return '---';
    if (dataTypes.length <= 0) return '---';
    const filterServiceAvailableByType = serviceAvailable?.filter(
      service => service.actionType === type,
    );
    const value = dataTypes
      .map(
        type =>
          filterServiceAvailableByType.find(service => service.id === type)
            ?.name,
      )
      .join(', ');
    return value;
  };

  const renderHistory = () => {
    return (
      <ScrollView style={{flex: 1}}>
        <View>
          <TextCM style={styles.txtLabel}>{t('DC.infoHistory')}</TextCM>
        </View>
        <View style={styles.groupItem}>
          {historyRecipients.map((item: any, index: number) => {
            return (
              <View key={index.toString()} style={styles.item}>
                <View style={styles.rowInfo}>
                  <TextCM style={styles.txtLabel}>{item?.name}</TextCM>
                  <TextCM style={(styles.txt500small, {color: item?.color})}>
                    • {item.textHistory}
                  </TextCM>
                </View>
                <View style={styles.rowInfo}>
                  <TextCM style={styles.txt400small}>{t('AI.TxtEmail')}</TextCM>
                  <TextCM style={styles.txt500small}>{item.email}</TextCM>
                </View>
                <View style={styles.rowInfo}>
                  <TextCM style={styles.txt400small}>{t('AI.TxtPhone')}</TextCM>
                  <TextCM style={styles.txt500small}>{item.phone}</TextCM>
                </View>
                <View style={styles.rowInfo}>
                  <TextCM style={styles.txt400small}>{t('AI.signDate')}</TextCM>
                  <TextCM style={styles.txt500small}>
                    {DateUtils.convertDateToDDMMYYYYhhmm(
                      recipentHistory?.signDate,
                    ) || '---'}
                  </TextCM>
                </View>
                <View style={styles.rowInfo}>
                  <TextCM style={styles.txt400small}>{t('AI.signType')}</TextCM>
                  <TextCM style={styles.txt500small}>
                    {getValue(recipentHistory?.signTypes, 'sign')}
                  </TextCM>
                </View>

                <View style={styles.rowInfo}>
                  <TextCM style={styles.txt400small}>
                    {t('AI.notifyType')}
                  </TextCM>
                  <TextCM style={styles.txt500small}>
                    {getValue(recipentHistory?.notifyTypes, 'notify')}
                  </TextCM>
                </View>
                {recipentHistory.status === 'rejected' && (
                  <View style={styles.rowInfo}>
                    <TextCM style={styles.txt400small}>{t('DC.reason')}</TextCM>
                    <TextCM
                      style={[
                        styles.txt500small,
                        {
                          fontFamily: Font.InterSemiBold600,
                          color: '#DA3E33',
                        },
                      ]}>
                      {recipentHistory?.reason || '---'}
                    </TextCM>
                  </View>
                )}
              </View>
            );
          })}
        </View>
      </ScrollView>
    );
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <View style={styles.ctnContainer}>
        <View style={styles.ctnTop} onTouchEnd={onClose} />
        <View style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
          <View style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IcBlackLeftArrow width={14} height={16} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>
              {t('DC.infoDetailRecipient')}
            </TextCM>
            <View />
          </View>
          <View style={styles.viewBody}>
            {renderHistory()}
            <ButtonCM onPress={onClose} label={t('CM.BtnClose')} />
          </View>
        </View>
      </View>
    </Modal>
  );
};

export default ModadlHistoryRecipient;
